// UPC-A with a valid check digit
function upc(n) {
  const base = ('850316' + String(n * 7919 % 100000).padStart(5, '0')).slice(0, 11);
  let sum = 0;
  for (let i = 0; i < 11; i++) sum += Number(base[i]) * (i % 2 === 0 ? 3 : 1);
  return base + ((10 - (sum % 10)) % 10);
}

