const now = Date.UTC(2026, 8, 20);
export const PRODUCTS = ROWS.map((r, i) => {
  const [slug, title, brand, cat, condition, price, originalPrice, shipping, inventory, bestDeal, description] = r;
  const imgs = (MANIFEST[slug] || []).map((n, k) => ({
    sm: `img/p/${slug}-${n}-sm.webp`,
    lg: `img/p/${slug}-${n}-lg.webp`,
    alt: k === 0 ? title : `${title} – view ${k + 1}`,
  }));
  return {
    id: 'p-' + String(i + 1).padStart(3, '0'),
    slug, title, brand, categoryId: C(cat), condition,
    price, originalPrice, shipping, inventory, bestDeal,
    published: true,
    noShipping: slug === 'live-bonsai-tree',
    upc: upc(i + 11),
    description,
    images: imgs,
    createdAt: new Date(now - i * 36e5 * 7).toISOString(),
  };
});
